def connect_ipv4(address):
    """Validate an IPv4 address and return it if valid."""
    if not isinstance(address, str):
        raise ValueError("invalid")

    parts = address.split(".")
    if len(parts) != 4:
        raise ValueError("invalid")

    for part in parts:
        # Must be non-empty and contain only digits
        if not part.isdigit():
            raise ValueError("invalid")
        # Must be a valid octet (0-255)
        value = int(part)
        if value < 0 or value > 255:
            raise ValueError("invalid")
        # Reject leading zeros (e.g., "01", "001") unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            raise ValueError("invalid")

    return address


def preview_ipv4(address):
    """Validate an IPv4 address and return a preview string."""
    if not isinstance(address, str):
        raise ValueError("invalid")

    parts = address.split(".")
    if len(parts) != 4:
        raise ValueError("invalid")

